import cv2import mssimport numpy as npimport osimport timefrom pynput import keyboard, mouseimport threadingfrom config import * # Import all settings from the config file# Create directories if they don't existos.makedirs(FRAME_DIR, exist_ok=True)# --- Main script ---# Get screen dimensions for mouse coordinate normalizationwith mss.mss() as sct:    monitor = sct.monitors[1]    SCREEN_WIDTH = monitor["width"]    SCREEN_HEIGHT = monitor["height"]print(f"Detected screen resolution: {SCREEN_WIDTH}x{SCREEN_HEIGHT}")print(f"Recording at {IMG_WIDTH}x{IMG_HEIGHT} @ {RECORDING_FPS} FPS")print(f"Keys being recorded: {len(COMMON_KEYS)}")# --- Global State Management ---pressed_keys = set()mouse_buttons = {'left': 0, 'right': 0}# Store mouse position as normalized coordinates (0.0 to 1.0)mouse_position = (0.5, 0.5)# Use a smoothed position for recording to reduce jitter from high-frequency mouse movementssmoothed_mouse_position = (0.5, 0.5)running = Truedata_lock = threading.Lock() # Thread-safe access to shared statedef get_key_str(key):    """Converts a pynput key object to a standardized string."""    if hasattr(key, 'char') and key.char:        return key.char.lower()    elif hasattr(key, 'name'):        # Standardize names (e.g., 'shift_r' -> 'shift')        return key.name.replace('_l', '').replace('_r', '')    return Nonedef on_key_press(key):    """Handles key press events."""    global running    # Use a dedicated quit key (F12) that is not in COMMON_KEYS    if key == keyboard.Key.f12:        print("🛑 Quit key (F12) pressed. Stopping recording...")        running = False        return        key_str = get_key_str(key)    if key_str in COMMON_KEYS:        with data_lock:            pressed_keys.add(key_str)def on_key_release(key):    """Handles key release events."""    key_str = get_key_str(key)    if key_str in COMMON_KEYS:        with data_lock:            pressed_keys.discard(key_str)def on_click(x, y, button, pressed):    """Handles mouse click events."""    with data_lock:        if button == mouse.Button.left:            mouse_buttons['left'] = int(pressed)        elif button == mouse.Button.right:            mouse_buttons['right'] = int(pressed)def on_move(x, y):    """Handles mouse movement events and applies smoothing."""    global mouse_position, smoothed_mouse_position    with data_lock:        # Normalize coordinates        raw_position = (x / SCREEN_WIDTH, y / SCREEN_HEIGHT)        mouse_position = raw_position                # Apply exponential moving average for smoothing        alpha = 0.3        smoothed_mouse_position = (            alpha * raw_position[0] + (1 - alpha) * smoothed_mouse_position[0],            alpha * raw_position[1] + (1 - alpha) * smoothed_mouse_position[1]        )def capture_frame():    """Captures and resizes a single screen frame."""    with mss.mss() as sct:        monitor = sct.monitors[1]        img = np.array(sct.grab(monitor))        # Convert from BGRA to RGB        img = cv2.cvtColor(img, cv2.COLOR_BGRA2RGB)        # Resize to the standard dimensions for the model        img = cv2.resize(img, (IMG_WIDTH, IMG_HEIGHT))        return imgdef get_current_action():    """Constructs the action vector for the current state."""    with data_lock:        # Create a binary vector for key presses        key_vector = [int(k in pressed_keys) for k in COMMON_KEYS]        # Use the smoothed mouse position for more stable training data        action = key_vector + list(smoothed_mouse_position) + [mouse_buttons['left'], mouse_buttons['right']]        return action.copy(), pressed_keys.copy()if __name__ == "__main__":    print("\n" + "="*50)    print("🟢 Starting HUMAN data recording in 5 seconds...")    print("   Play the game normally.")    print("   Press [F12] to quit.")    print("="*50 + "\n")    time.sleep(5)        # Start listeners in separate threads    key_listener = keyboard.Listener(on_press=on_key_press, on_release=on_key_release)    mouse_listener = mouse.Listener(on_click=on_click, on_move=on_move)    key_listener.start()    mouse_listener.start()        actions = []    frame_interval = 1.0 / RECORDING_FPS    i = 0        try:        last_capture_time = time.time()        while running:            current_time = time.time()            if current_time - last_capture_time >= frame_interval:                last_capture_time = current_time                                frame = capture_frame()                action, current_keys = get_current_action()                                # Save frame and action                frame_path = os.path.join(FRAME_DIR, f"frame_{i:06d}.jpg")                cv2.imwrite(frame_path, cv2.cvtColor(frame, cv2.COLOR_RGB2BGR))                actions.append(action)                                # Log output to console                if current_keys or action[-1] or action[-2]:                    print(f"Frame {i}: keys={list(current_keys)}, mouse=({action[-4]:.2f}, {action[-3]:.2f}), click_L={action[-2]}, click_R={action[-1]}")                                i += 1                        # Sleep briefly to prevent high CPU usage            time.sleep(0.001)                finally:        # Cleanly stop listeners        key_listener.stop()        mouse_listener.stop()                if actions:            actions_array = np.array(actions, dtype=np.float32)            actions_path = os.path.join(DATA_DIR, ACTIONS_FILE)            np.save(actions_path, actions_array)            print(f"\n✅ Saved {len(actions)} actions and frames to {DATA_DIR}.")        else:            print("\nNo actions were recorded!")